create or replace function public.fleet_dashboard_summary_v2(p_business_id uuid) returns jsonb language plpgsql stable security definer set search_path to 'public' as $$ declare v_allowed boolean; v jsonb; begin v_allowed:=public.has_fleet_access(p_business_id); if not v_allowed then raise exception 'Fleet access required'; end if; with veh as (select count(*) total,count(*) filter(where status='active') active,coalesce(sum(odometer_miles),0) odometer from public.fleet_vehicles where business_id=p_business_id),drv as (select count(*) total,count(*) filter(where status='active') active from public.fleet_drivers where business_id=p_business_id),rte as (select count(*) total,count(*) filter(where status='active') active,count(*) filter(where status in ('completed','complete')) completed,coalesce(sum(distance_miles),0) miles,coalesce(sum(estimated_minutes),0) minutes from public.fleet_routes where business_id=p_business_id),alt as (select count(*) filter(where status='open') open,count(*) total from public.fleet_alerts where business_id=p_business_id),ops as (select count(*) events,count(*) filter(where lower(event_type) in ('hard_brake','hard_braking','harsh_braking','hard_acceleration','harsh_acceleration','speeding','collision','seatbelt')) safety_events,coalesce(sum(event_value) filter(where unit ilike '%mile%'),0) miles,coalesce(sum(event_value) filter(where unit ilike '%minute%'),0) minutes from public.fleet_operational_events where business_id=p_business_id),maint as (select count(*) filter(where status in ('scheduled','due','overdue')) due,coalesce(sum(cost) filter(where completed_at is not null),0) maintenance_spend from public.fleet_maintenance_records where business_id=p_business_id),loc as (select count(*) total,count(*) filter(where bathroom_verification_status in ('verified','user_verified','business_verified')) verified,count(*) filter(where accessible=true) accessible,count(*) filter(where changing_table=true) changing_tables from public.locations where is_active=true and business_id=p_business_id),opp as (select count(*) opportunities,count(*) filter(where needs_fresh_observation=1) stale_opportunities from public.fleet_service_opportunities where business_id=p_business_id) select jsonb_build_object('vehicles',veh.total,'vehicles_active',veh.active,'odometer_miles',veh.odometer,'drivers',drv.total,'drivers_active',drv.active,'routes',rte.total,'routes_active',rte.active,'routes_completed',rte.completed,'route_miles',rte.miles,'route_minutes',rte.minutes,'open_alerts',alt.open,'alerts_total',alt.total,'operational_events',ops.events,'safety_events',ops.safety_events,'telemetry_miles',ops.miles,'telemetry_minutes',ops.minutes,'maintenance_due',maint.due,'maintenance_spend',maint.maintenance_spend,'location_total',loc.total,'location_verified',loc.verified,'location_accessible',loc.accessible,'location_changing_tables',loc.changing_tables,'service_opportunities',opp.opportunities,'stale_service_opportunities',opp.stale_opportunities) into v from veh cross join drv cross join rte cross join alt cross join ops cross join maint cross join loc cross join opp; return v; end $$;
